create or replace view public.goal_values with(security_invoker=true) as select g.id,g.owner_id,g.account_id,g.name,g.kind,g.target::text,g.target_date,g.priority,g.monthly_plan::text,g.essential_monthly::text,g.archived,coalesce(sum(e.amount),0)::text as funded,max(e.effective_date) filter(where e.amount>0 and e.reason in ('Manual contribution','Confirmed income allocation') and (e.batch_id is null or exists(select 1 from public.allocation_batches b where b.id=e.batch_id and not b.undone))) as last_contribution from public.goals g left join public.goal_events e on e.goal_id=g.id group by g.id;
